import fs from 'node:fs';import{pathToFileURL}from'node:url';
const base=new URL('.',pathToFileURL(process.argv[2]));const{McpHost}=await import(new URL('host.js',base));const{DeterministicLiveSimulator,LiveMutationNotDispatchedError}=await import(new URL('live.js',base));
function clean(v){v=structuredClone(v);function walk(x){if(!x||typeof x!=='object')return;for(const[k,w]of Object.entries(x)){if(typeof w==='string'&&/^(devdel|clipdel|trackdel|scenedel|locatordel)_/.test(w))x[k]='$transaction';else if(k==='expiresAt')x[k]='$time';else walk(w);}}if(v?.result?.content?.[0]?.text)try{v.result.content[0].text=JSON.parse(v.result.content[0].text)}catch{}walk(v);return v}
const variants={device:['device','device:utility-1'],nested:['device','device:inside'],clip:['clip','clip:clip-1'],arrangement:['clip','arrangement-clip:target'],take:['clip','take-clip:one'],scene:['scene','scene:scene-1'],lastscene:['scene','scene:scene-1'],track:['track','track:track-1'],group:['track','track:track-1'],main:['track','track:track-1'],return:['track','track:track-1'],locator:['locator','locator:locator-1']};
const seeds={};for(const kind of Object.keys(variants)){const sim=new DeterministicLiveSimulator(),track=sim.state.tracks[0];
if(['main','return','group'].includes(kind))track.kind=kind;
if(kind==='nested')track.devices[0].chains=[{ref:'chain:one',parentRef:track.devices[0].ref,objectIdentity:'chain:identity',name:'Chain',index:0,mute:false,solo:false,devices:[{...structuredClone(track.devices[0]),ref:'device:inside',objectIdentity:'device:inside-id'}]}];
if(kind==='arrangement')sim.state.arrangementClips=[{trackRef:track.ref,clip:{...structuredClone(track.clips[0]),ref:'arrangement-clip:target',objectIdentity:'arrangement:identity',start:8}}];
if(kind==='take')track.takeLanes=[{ref:'take-lane:one',parentRef:track.ref,objectIdentity:'lane:identity',name:'Take',index:0,clips:[{...structuredClone(track.clips[0]),ref:'take-clip:one',objectIdentity:'take:identity'}]}];
if(kind==='lastscene')sim.state.scenes=sim.state.scenes.slice(0,1);
if(kind==='group'){for(const [i,parent]of [[2,track.ref],[3,'track:child2']])sim.state.tracks.push({...structuredClone(track),ref:'track:child'+i,objectIdentity:'child:'+i,name:'Child '+i,groupTrackRef:parent,kind:i===2?'group':'regular',index:i-1,devices:[],clips:[],clipSlots:[]});}
seeds[kind]=structuredClone(sim.state);}
const args=kind=>({[variants[kind][0]==='device'?'ref':variants[kind][0]+'Ref']:variants[kind][1]});
const rows=[];for(const kind of ['device','clip','track','scene','locator'])for(const action of ['preview','apply']){const valid=action==='preview'?args(kind):{transactionId:'missing',confirmation:'apply',idempotencyKey:'apply-key'};const cases=[null,[],{},0,false,'x',valid,{...valid,extra:true}];for(const key of Object.keys(valid)){const omitted={...valid};delete omitted[key];cases.push(omitted);for(const value of [null,[],{},false,true,-1,0,1,'','x','a'.repeat(257)])cases.push({...valid,[key]:value})}for(const p of cases){const sim=new DeterministicLiveSimulator();Object.assign(sim.state,structuredClone(seeds[kind]));const host=new McpHost(sim);rows.push({kind,action,args:p,result:clean(kind==='device'?await host[action==='preview'?'liveDeviceDeletePreviewAsync':'liveDeviceDeleteApplyAsync'](1,p):await host[action==='preview'?'liveDeletionPreviewAsync':'liveDeletionApplyAsync'](1,p,kind))})}}
const workflows=[];for(const kind of Object.keys(variants))for(const scenario of ['normal','expire','epoch','identity-edit','content-edit','structure-edit','missing-identity','apply-before','apply-after','apply-refusal','apply-no-effect','apply-read','apply-current-read','apply-preabort']){
const sim=new DeterministicLiveSimulator();Object.assign(sim.state,structuredClone(seeds[kind]));const calls=[],cache=new Map();let fault='',fired=false,afterInvoke=false;if(scenario==='missing-identity')sim.state.tracks[0].objectIdentity='';
function context(c){return c?{deadline:c.deadlineMs!==undefined,...(c.idempotencyKey?{idempotencyKey:c.idempotencyKey}:{}),...(c.transactionId?{transactionId:c.transactionId}:{})}:null}
function readFault(){if(!fired&&((fault.endsWith('-read')&&afterInvoke)||fault==='apply-current-read'||fault==='undo-current-read')){fired=true;throw Error('injected authoritative read failure')}}
function invoke(i,c){calls.push(clean({method:'invoke',invocation:i,context:context(c)}));const key=JSON.stringify([c?.transactionId,c?.idempotencyKey,i]);if(cache.has(key))return structuredClone(cache.get(key));if(!fired&&['before','refusal'].some(s=>fault.endsWith(s))){fired=true;throw fault.endsWith('refusal')?new LiveMutationNotDispatchedError('mutation was not dispatched: ownership changed'):Error('injected operation failure')}const noEffect=!fired&&fault.endsWith('no-effect');const result=noEffect?{ok:true}:sim.invoke(i);if(noEffect)fired=true;else cache.set(key,structuredClone(result));afterInvoke=true;if(!fired&&fault.endsWith('after')){fired=true;throw Error('injected operation failure')}if(!fired&&['apply-invalid-identity','apply-invalid-fingerprint','apply-no-fingerprint'].includes(fault)){fired=true;result[fault.endsWith('identity')?'objectIdentity':'createdFingerprint']='';if(fault==='apply-no-fingerprint')delete result.createdFingerprint}return result}
const adapter={status:()=>sim.status(),snapshot:()=>sim.snapshot(),get:r=>sim.get(r),invoke:i=>invoke(i),subscribe:l=>sim.subscribe(l),reconnect:()=>sim.reconnect(),snapshotAsync:async(c,r)=>{calls.push(clean({method:'snapshot',request:r??null,context:context(c)}));readFault();return sim.snapshotAsync(c,r)},discoverAsync:async(r,c)=>{calls.push(clean({method:'discover',request:r,context:context(c)}));readFault();return sim.discoverAsync(r,c)},getAsync:async(r,c)=>{calls.push(clean({method:'get',reference:r,context:context(c)}));readFault();return sim.get(r)},invokeAsync:async(i,c)=>invoke(i,c),refreshStatusAsync:async c=>{calls.push(clean({method:'status',context:context(c)}));return sim.status()}};

const host=new McpHost(adapter),results=[],states=[],type=variants[kind][0];const preview=type==='device'?await host.liveDeviceDeletePreviewAsync(1,args(kind)):await host.liveDeletionPreviewAsync(1,args(kind),type);results.push(clean(preview));const txid=JSON.parse(preview.result.content[0].text).transactionId;
if(txid){const record=host.clipLifecycleTransactions.get(txid);if(scenario==='expire')record.expiresAt=0;if(scenario==='epoch')sim.reconnect();if(scenario==='identity-edit')sim.state.tracks[0].objectIdentity='other';if(scenario==='content-edit')sim.state.tracks[0].devices[0].name='Manual';if(scenario==='structure-edit')sim.state.scenes[0].name='Changed';if(scenario.startsWith('apply-'))fault=scenario;
for(const key of ['apply-key','other-key','apply-key']){const p={transactionId:txid,confirmation:'apply',idempotencyKey:key};const controller=new AbortController();if(scenario==='apply-preabort')controller.abort();results.push(clean(type==='device'?await host.liveDeviceDeleteApplyAsync(results.length+1,p,controller.signal):await host.liveDeletionApplyAsync(results.length+1,p,type,controller.signal)));states.push(clean(record));}
fault='';fired=false;afterInvoke=false;results.push(clean(await host.liveUndoAsync(results.length+1,{transactionId:txid,confirmation:'undo',idempotencyKey:'undo-key'})));states.push(clean(record));}
workflows.push({kind,scenario,results,states,calls,state:sim.state});}
fs.writeFileSync(new URL('host-deletion-oracle.json',import.meta.url),JSON.stringify({seeds,variants,rows,workflows}));console.log({rows:rows.length,workflows:workflows.length});
